SELECT bb.qc_treatment_id AS qcTreatmentId, bb.adm_no AS admNo, bb.customer_name AS customerName, bb.customer_mobile AS customerMobile, bb.name AS patientName, bb.type, bb.bill_num AS billNum, bbp.payee_date AS payeeDate, IFNULL(bb.received_amount, 0) AS billReceivedAmount, IFNULL(bqt.executed_amount, 0) AS adviceItemExecAmount, IFNULL(bqt.un_executed_amount, 0) AS adviceItemUnExecAmount FROM base_bill_pay bbp INNER JOIN ( SELECT bb.bill_id, bb.bill_num, bb.received_amount, bqt.qc_treatment_id, bqt.adm_no, bqt.customer_name, bqt.customer_mobile, bqt.type, bp.name, bp.pinyin_name, bp.mobile FROM base_bill bb LEFT JOIN base_qcyl_treatment bqt ON bb.bill_id=bb.bill_id LEFT JOIN base_patient bp ON bp.patient_id=bqt.patient_id ) bb ON bb.bill_id = bbp.bill_id LEFT JOIN base_qcyl_treatment bqt ON bqt.bill_pay_id=bbp.bill_pay_id
AND CONCAT(IFNULL(bb.name, ''),IFNULL(bb.pinyin_name, ''), IFNULL(bp.mobile, '')) LIKE CONCAT('%', #{query.keyWord}, '%')
and DATE_FORMAT( bbp.payee_date, '%Y-%m-%d' ) >= #{query.startDate}
and DATE_FORMAT( bbp.payee_date, '%Y-%m-%d' ) <= #{query.endDate}
and DATE_FORMAT( bbp.payee_date, '%Y-%m' ) >= #{query.startDate}
and DATE_FORMAT( bbp.payee_date, '%Y-%m' ) <= #{query.endDate}
and DATE_FORMAT( bbp.payee_date, '%Y' ) >= #{query.startDate}
and DATE_FORMAT( bbp.payee_date, '%Y' ) <= #{query.endDate}

SELECT bb.qc_treatment_id AS qcTreatmentId, bb.adm_no AS admNo, bb.customer_name AS customerName, bb.customer_mobile AS customerMobile, bb.name AS patientName, bb.type, bb.bill_num AS billNum, bbp.payee_date AS payeeDate, bbp.received_amount - IFNULL(bqt.executed_amount, 0) AS receivedAmount FROM base_bill_pay bbp INNER JOIN ( SELECT bb.bill_id, bb.bill_num, bb.received_amount, bqt.qc_treatment_id, bqt.adm_no, bqt.customer_name, bqt.customer_mobile, bp.name FROM base_bill bb LEFT JOIN base_qcyl_treatment bqt ON bb.bill_id=bb.bill_id LEFT JOIN base_patient bp ON bp.patient_id=bqt.patient_id ) bb ON bb.bill_id = bbp.bill_id LEFT JOIN base_qcyl_treatment bqt ON bqt.bill_pay_id=bbp.bill_pay_id
AND IFNULL(bb.customer_name, '') LIKE CONCAT('%', #{query.keyWord}, '%')
and DATE_FORMAT( bbp.payee_date, '%Y-%m-%d' ) >= #{query.startDate}
and DATE_FORMAT( bbp.payee_date, '%Y-%m-%d' ) <= #{query.endDate}
and DATE_FORMAT( bbp.payee_date, '%Y-%m' ) >= #{query.startDate}
and DATE_FORMAT( bbp.payee_date, '%Y-%m' ) <= #{query.endDate}
and DATE_FORMAT( bbp.payee_date, '%Y' ) >= #{query.startDate}
and DATE_FORMAT( bbp.payee_date, '%Y' ) <= #{query.endDate}

SELECT
    bqt.qc_treatment_id AS qcTreatmentId,
    bqt.adm_no AS admNo,
    bb.bill_date AS billDate,
    bp.name AS patientName,
    bp.mobile,
    IFNULL(bb.received_amount, 0) AS receivedTotalAmount,
    bqt.execute_amount AS adviceItemExecAmount,
    bqt.un_execute_amount AS unAdviceItemExecAmount,
    IFNULL(bb.received_amount, 0) - bqt.execute_amount AS orderItemExecAmount
FROM base_qcyl_treatment bqt
LEFT JOIN base_bill bb ON bqt.bill_id = bb.bill_id
LEFT JOIN base_patient bp ON bp.patient_id = bqt.patient_id

    AND status = 3


